    VALUES (N'Mobile Crisis', N'Day 14 follow-up: services engaged and plan holding', @tenant, N'FU-02', N'FU', N'FOLLOW_UP', N'Follow-up', N'Follow-up', N'Reached / services engaged / crisis recurrence', N'Day 14', N'QP / Peer', 1, N'Seed', 1, NULL);
    SET @g = SCOPE_IDENTITY();
    SET @o = SCOPE_IDENTITY();
    SET @o = SCOPE_IDENTITY();
    SET @o = SCOPE_IDENTITY();
END
IF NOT EXISTS (SELECT 1 FROM ClientGoalsLibrary WHERE Code = N'FU-03')
BEGIN
    VALUES (N'Mobile Crisis', N'Day 21 follow-up and episode close', @tenant, N'FU-03', N'FU', N'FOLLOW_UP', N'Follow-up', N'Follow-up', N'Reached / episode closed without recurrence', N'Day 21', N'QP', 1, N'Seed', 1, NULL);
    SET @g = SCOPE_IDENTITY();
    SET @o = SCOPE_IDENTITY();
    SET @o = SCOPE_IDENTITY();
END

-- Link E3 goals to their E4 continuation
